-- MTC TEAMUP -> NEW APP FUTURE CLASS + BOOKING MIGRATION
-- Source exports supplied 1 Oct 2026.
-- Scope: 2 Oct 2026 onward.
-- Safe to re-run: sessions and bookings are protected with NOT EXISTS checks.
-- IMPORTANT: TeamUp's All Events export does not include class capacity.
-- For a brand-new session this uses the matching class_schedules capacity when one
-- unambiguously matches by title + weekday + start time; otherwise it uses at least 12
-- and never less than the TeamUp attendee count.

begin;

create temp table teamup_future_sessions (
  starts_at timestamptz not null,
  title text not null,
  location text,
  duration_min integer not null,
  attendee_count integer not null
) on commit drop;

insert into teamup_future_sessions
  (starts_at, title, location, duration_min, attendee_count)
