-- Preserve any TeamUp registration whose MTC auth account does not exist yet.
-- This contains only the minimum booking data needed to attach it later.
create table if not exists public.teamup_booking_migration_pending (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  starts_at timestamptz not null,
  title text not null,
  location text,
  created_at timestamptz not null default now()
);

create unique index if not exists teamup_booking_migration_pending_unique
on public.teamup_booking_migration_pending
(lower(trim(email)), starts_at, lower(trim(title)), lower(trim(coalesce(location, ''))));

-- Insert missing future sessions.
-- Deduplicate the TeamUp source before insert because more than one TeamUp row can
-- map to the same MTC schedule_id + starts_at. The database unique constraint is
-- also used as the final guard against collisions with already-generated sessions.
with resolved as (
  select
    s_match.id as schedule_id,
    t.title,
    s_match.category,
    t.location,
    s_match.coach_id,
    t.starts_at,
    t.starts_at + make_interval(mins => t.duration_min) as ends_at,
    greatest(coalesce(s_match.capacity, 12), t.attendee_count) as capacity,
    row_number() over (
      partition by s_match.id, t.starts_at
      order by t.attendee_count desc, t.title, coalesce(t.location, '')
    ) as scheduled_rn,
    row_number() over (
      partition by t.starts_at, lower(trim(t.title)), lower(trim(coalesce(t.location, '')))
      order by t.attendee_count desc
    ) as unscheduled_rn
  from teamup_future_sessions t
  left join lateral (
    select s.*
    from public.class_schedules s
    where s.active = true
      and lower(trim(s.title)) = lower(trim(t.title))
      and s.start_time = (t.starts_at at time zone 'Europe/London')::time
      and s.weekday = extract(dow from (t.starts_at at time zone 'Europe/London'))::integer
    order by s.updated_at desc
    limit 1
  ) s_match on true
), to_insert as (
  select *
  from resolved r
  where
    (r.schedule_id is not null and r.scheduled_rn = 1)
    or
    (r.schedule_id is null and r.unscheduled_rn = 1)
)
insert into public.class_sessions (
  schedule_id, title, category, location, coach_id, starts_at, ends_at,
  capacity, cancelled, notes
)
select
  r.schedule_id, r.title, r.category, r.location, r.coach_id, r.starts_at,
  r.ends_at, r.capacity, false,
  'Imported from TeamUp future schedule on 2026-10-01'
from to_insert r
where not exists (
  select 1
  from public.class_sessions cs
  where cs.starts_at = r.starts_at
    and (
      (r.schedule_id is not null and cs.schedule_id = r.schedule_id)
      or
      (
        r.schedule_id is null
        and cs.schedule_id is null
        and lower(trim(cs.title)) = lower(trim(r.title))
        and lower(trim(coalesce(cs.location, ''))) = lower(trim(coalesce(r.location, '')))
      )
    )
)
on conflict (schedule_id, starts_at) do nothing;

-- Make matching existing sessions agree with TeamUp's title/location/duration.
-- Capacity is never reduced because the TeamUp report does not expose capacity.
update public.class_sessions cs
set
  title = t.title,
  location = t.location,
  ends_at = t.starts_at + make_interval(mins => t.duration_min),
  capacity = greatest(cs.capacity, t.attendee_count),
  updated_at = now()
from teamup_future_sessions t
where cs.starts_at = t.starts_at
  and lower(trim(cs.title)) = lower(trim(t.title))
  and lower(trim(coalesce(cs.location, ''))) = lower(trim(coalesce(t.location, '')));

-- Preserve bookings for anyone who has not created an MTC auth account yet.
insert into public.teamup_booking_migration_pending
  (email, starts_at, title, location)
select
  lower(trim(tb.email)),
  tb.starts_at,
  tb.title,
  tb.location
from teamup_future_bookings tb
left join auth.users u
  on lower(trim(u.email)) = lower(trim(tb.email))
where u.id is null
on conflict do nothing;

-- Carry existing TeamUp registrations into the new MTC booking system.
-- No pack credit is consumed for a migrated booking.
-- Migration exception: these are pre-existing TeamUp reservations.
-- Disable ONLY the trigger(s) on public.bookings whose trigger function is
-- mtc_enforce_booking_compliance(). Normal booking compliance remains unchanged
-- before and after this transaction.
do $migration$
declare
  r record;
begin
  for r in
    select t.tgname
    from pg_trigger t
    join pg_proc p on p.oid = t.tgfoid
    where t.tgrelid = 'public.bookings'::regclass
      and not t.tgisinternal
      and p.proname = 'mtc_enforce_booking_compliance'
  loop
    execute format(
      'alter table public.bookings disable trigger %I',
      r.tgname
    );
  end loop;
end
$migration$;

insert into public.bookings (
  session_id,
  user_id,
  status,
  used_pack_credit,
  booked_at
)
select
  cs.id,
  u.id,
  'booked',
  false,
  now()
from teamup_future_bookings tb
join auth.users u
  on lower(trim(u.email)) = lower(trim(tb.email))
join public.class_sessions cs
  on cs.starts_at = tb.starts_at
 and lower(trim(cs.title)) = lower(trim(tb.title))
 and lower(trim(coalesce(cs.location, ''))) = lower(trim(coalesce(tb.location, '')))
where not exists (
  select 1
  from public.bookings b
  where b.session_id = cs.id
    and b.user_id = u.id
    and b.managed_child_id is null
    and b.status = 'booked'
);
-- Immediately restore the booking compliance trigger(s).
do $migration$
declare
  r record;
begin
  for r in
    select t.tgname
    from pg_trigger t
    join pg_proc p on p.oid = t.tgfoid
    where t.tgrelid = 'public.bookings'::regclass
      and not t.tgisinternal
      and p.proname = 'mtc_enforce_booking_compliance'
  loop
    execute format(
      'alter table public.bookings enable trigger %I',
      r.tgname
    );
  end loop;
end
$migration$;


commit;

-- VERIFICATION
select
  (select count(*) from public.class_sessions
   where starts_at >= '2026-10-02 00:00:00 Europe/London'::timestamptz) as future_sessions_in_mtc,
  (select count(*) from public.teamup_booking_migration_pending) as unmatched_teamup_bookings;

select
  p.email,
  p.title,
  p.starts_at at time zone 'Europe/London' as class_time_uk,
  p.location
from public.teamup_booking_migration_pending p
order by p.starts_at, p.email;
